	    public void EncodeBase64NVARCHARFields(ObjectTablePM entityPM)
        {
            if (String.IsNullOrWhiteSpace(entityPM.EncodeBase64NVARCHARFieldsBy)) 
            {
                return;
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SplitComponentPath)) //T4 find type == nText 
            {
                entityPM.SplitComponentPath = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SplitComponentPath));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.SearchFields)) //T4 find type == nText 
            {
                entityPM.SearchFields = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.SearchFields));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.LovDisplayMemberPath)) //T4 find type == nText 
            {
                entityPM.LovDisplayMemberPath = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.LovDisplayMemberPath));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.LovDisplayMemberPathLocal)) //T4 find type == nText 
            {
                entityPM.LovDisplayMemberPathLocal = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.LovDisplayMemberPathLocal));
            }
            if (!String.IsNullOrWhiteSpace(entityPM.HashString)) //T4 find type == nText 
            {
                entityPM.HashString = Encoding.GetEncoding(entityPM.EncodeBase64NVARCHARFieldsBy).GetString(Convert.FromBase64String(entityPM.HashString));
            }
            entityPM.EncodeBase64NVARCHARFieldsBy=null;
		}
